export function getPostBySlug(slug) {
  return blogPosts.find((p) => p.slug === slug)
}

// Newest-first order for listing pages. The source array above is in the
// order posts were added to the file (oldest first), so without this,
// freshly added posts sink to the very bottom of /blog instead of showing
// at the top where readers (and crawlers) actually look.
export function getSortedBlogPosts() {
  return [...blogPosts].sort((a, b) => new Date(b.isoDate) - new Date(a.isoDate))
}

// Picks up to `count` posts related to `post` — favours posts that share a
// tag with it, then fills any remaining slots with other posts, all in a
// per-post-varied order (seeded by the post's own id) rather than always
// the same three posts on every article page.
export function getRelatedPosts(post, count = 3) {
  const others = blogPosts.filter((p) => p.slug !== post.slug)
  const seed = post.id || 0

  const shared = (p) => (p.tags || []).filter((t) => post.tags?.includes(t)).length

  const withScores = others
    .map((p, i) => ({ p, score: shared(p), order: (i + seed) % others.length }))
    .sort((a, b) => b.score - a.score || a.order - b.order)

  return withScores.slice(0, count).map((x) => x.p)
}
